def json_dumps(item, default_mapping=None, force_use_builtin_json: bool=False, **kwargs):
    if orjson is not None and not force_use_builtin_json:
        if kwargs:
            raise TypeError('orjson does not accept the {} parameter.'.format(', '.join(kwargs.keys())))
        return orjson.dumps(item, default=json_convertor_default(default_mapping)).decode('utf-8')
    else:
        return json.dumps(item, default=json_convertor_default(default_mapping), **kwargs)

def object_hook(self, obj):
    if 'old_type' in obj and 'new_type' in obj:
        for type_key in ('old_type', 'new_type'):
            type_str = obj[type_key]
            obj[type_key] = TYPE_STR_TO_TYPE.get(type_str, type_str)
    return obj
